/* Template:TreeCombo/styles.css - cards for the trees that pair well with a tree. The cards sit in two fixed columns (.aa-tc-col), so a hover card never makes anything move. The icons come from one picture
   (File:Skill.png), the same one and the same windows as the Main Page (Template:MainPage/styles.css).
   No overflow is hidden on the card, so the hover cards of the skill links are not cut off. */
.aa-tc-grid {
	display: flex;
	flex-wrap: wrap;
	align-items: flex-start;
	gap: 0 10px;
	margin: 0.6em 0 0.4em;
}
.aa-tc-col {
	flex: 1 1 270px;
	min-width: 0;
}
.aa-tc {
	display: block;
	box-sizing: border-box;
	margin: 0 0 10px;
	padding: 10px 12px 12px;
	border: 1px solid var(--border-color-base, #a2a9b1);
	border-radius: 6px;
	background: var(--color-surface-2, #f8f9fa);
}
.aa-tc-head {
	display: flex;
	align-items: center;
	gap: 10px;
}
.aa-tc-name {
	font-size: 1.1em;
	font-weight: bold;
	line-height: 1.2;
}
.aa-tc-role {
	color: var(--color-subtle, #54595d);
	font-size: 0.85em;
	line-height: 1.3;
}
.aa-tc-rows {
	margin-top: 8px;
	padding-top: 2px;
	border-top: 1px solid var(--border-color-base, #a2a9b1);
}
.aa-tc-row {
	margin-top: 8px;
}
.aa-tc-lbl {
	display: block;
	color: var(--color-subtle, #54595d);
	font-size: 0.72em;
	letter-spacing: 0.06em;
	text-transform: uppercase;
}
.aa-tc-items {
	display: flex;
	flex-wrap: wrap;
	gap: 3px 14px;
	margin-top: 2px;
}

/* the tree icon: a 40px window onto File:Skill.png */
.aa-tc-ico {
	position: relative;
	flex: none;
	width: 40px;
	height: 40px;
	overflow: hidden;
}
.aa-tc-ico a,
.aa-tc-ico span {
	display: block;
	width: 100%;
	height: 100%;
}
.aa-tc-ico img {
	position: absolute;
	max-width: none;
	width: 660px;
	height: auto;
}
